% =========================================================================
% plot_saved_results.m
%
% Loads saved simulation results generated by the main script 
% (main_plot_error_rates_n_fixed_E2_vec.m) and plots the exact same image.
%
% Supports loading either:
%   1. 'summary_all_n.mat' (summary file containing all data vectors)
%   2. Individual 'result_n_*.mat' files in the target results directory
% =========================================================================
clear; close all;

% --- 1. Simulation / Result Parameters ---
func_type = 'id';  % Function type: 'exact-threshold', 'id', etc.
E2 = 0.10;                      % Parameter E2

% Target results directory
results_dir = fullfile('results', sprintf('%s_E2_%.2f', func_type, E2));

if ~exist(results_dir, 'dir')
    error('Results directory not found: %s', results_dir);
end

fprintf('=== Loading Saved Results ===\n');
fprintf('Results directory: %s\n', results_dir);

% --- 2. Load Results Data ---
summary_file = fullfile(results_dir, 'summary_all_n.mat');

if exist(summary_file, 'file')
    fprintf('Found summary file "%s". Loading dataset...\n', summary_file);
    loaded_data = load(summary_file);
    
    n_list_sim              = loaded_data.n_list_sim;
    sim_r_vals              = loaded_data.sim_r_vals;
    sim_K_vals              = loaded_data.sim_K_vals;
    sim_L_vals              = loaded_data.sim_L_vals;
    sim_error_prob          = loaded_data.sim_error_prob;
    sim_error_prob_baseline = loaded_data.sim_error_prob_baseline;
    sim_S_weights           = loaded_data.sim_S_weights;
    sim_rates               = loaded_data.sim_rates;
    expected_FP_rates       = loaded_data.expected_FP_rates;
    theory_upper_bound      = loaded_data.theory_upper_bound;
else
    fprintf('Summary file not found. Reconstructing from individual result_n_*.mat files...\n');
    mat_files = dir(fullfile(results_dir, 'result_n_*.mat'));
    
    if isempty(mat_files)
        error('No result_n_*.mat files found in %s', results_dir);
    end
    
    num_files = length(mat_files);
    temp_n        = zeros(1, num_files);
    temp_r        = zeros(1, num_files);
    temp_K        = zeros(1, num_files);
    temp_L        = zeros(1, num_files);
    temp_err      = zeros(1, num_files);
    temp_err_base = zeros(1, num_files);
    temp_S        = zeros(1, num_files);
    temp_rate     = zeros(1, num_files);
    temp_exp_fp   = zeros(1, num_files);
    
    for k = 1:num_files
        file_path = fullfile(results_dir, mat_files(k).name);
        res = load(file_path);
        
        temp_n(k)      = res.n;
        temp_r(k)      = res.r;
        temp_K(k)      = res.K;
        temp_L(k)      = res.L;
        temp_S(k)      = res.S;
        temp_rate(k)   = res.rate;
        temp_exp_fp(k) = res.expected_FP;
        
        if isfield(res, 'stat')
            temp_err(k)      = res.stat.error_prob;
            temp_err_base(k) = res.stat.error_prob_baseline;
        else
            temp_err(k)      = res.error_prob;
            temp_err_base(k) = res.error_prob_baseline;
        end
    end
    
    % Sort by n in ascending order
    [n_list_sim, idx] = sort(temp_n);
    sim_r_vals              = temp_r(idx);
    sim_K_vals              = temp_K(idx);
    sim_L_vals              = temp_L(idx);
    sim_error_prob          = temp_err(idx);
    sim_error_prob_baseline = temp_err_base(idx);
    sim_S_weights           = temp_S(idx);
    sim_rates               = temp_rate(idx);
    expected_FP_rates       = temp_exp_fp(idx);
    
    % Compute continuous upper bound: S * (K - 1) / L
    theory_upper_bound = (sim_S_weights .* (sim_K_vals - 1)) ./ sim_L_vals;
end

fprintf('Successfully loaded %d data points for n = %s\n', length(n_list_sim), mat2str(n_list_sim));

% --- 3. Recreate Plot ---
figure('Name', 'BFC Error Probability (Loaded Results)', 'Color', 'w', 'Position', [100, 100, 800, 600]);

% Using semilogy for log scale on the Y-axis
semilogy(n_list_sim, sim_error_prob, 'bo-', 'LineWidth', 2, 'MarkerSize', 8, 'DisplayName', 'Simulated Empirical FP');
hold on;
semilogy(n_list_sim, sim_error_prob_baseline, 'bx-', 'LineWidth', 2, 'MarkerSize', 8, 'DisplayName', 'Baseline (always decode 0)');
semilogy(n_list_sim, theory_upper_bound, 'r--', 'LineWidth', 2, 'DisplayName', 'Upper Bound: S(K-1)/L');
semilogy(n_list_sim, expected_FP_rates, 'g-.', 'LineWidth', 2, 'DisplayName', 'Expected FP');

% Ensure Y-axis is explicitly set to log scale
set(gca, 'YScale', 'log');

% Annotate rate (R) values near each data point
for i = 1:length(n_list_sim)
    if sim_error_prob(i) > 0
        if i == length(n_list_sim)
            text(n_list_sim(i) - 0.5, sim_error_prob(i) * 1.3, sprintf('R=%.3f', sim_rates(i)), 'Color', 'b', 'FontSize', 12, 'FontWeight', 'bold');
        elseif i == 1
            text(n_list_sim(i) + 0.2, sim_error_prob(i) * 1.3, sprintf('R=%.3f', sim_rates(i)), 'Color', 'b', 'FontSize', 12, 'FontWeight', 'bold');
        else
            text(n_list_sim(i) - 0.2, sim_error_prob(i) * 1.3, sprintf('R=%.3f', sim_rates(i)), 'Color', 'b', 'FontSize', 12, 'FontWeight', 'bold');
        end
    end
end

% Formatting options
grid on;
grid minor;
xlabel('n = log_2(L) + r', 'FontSize', 12, 'FontWeight', 'bold');
ylabel('Error Probability (Log Scale)', 'FontSize', 12, 'FontWeight', 'bold');
title(sprintf('BFC Error Rate vs. n (E2=%.2f, %s)', E2, func_type), 'FontSize', 14);
legend('Location', 'southwest', 'FontSize', 11);
xlim([floor(n_list_sim(1)), ceil(n_list_sim(end))]);

% Dynamic Y-axis limits
valid_errs = sim_error_prob(sim_error_prob > 0);
if ~isempty(valid_errs)
    ylim([max(1e-6, min(valid_errs) * 0.1), 1]);
else
    ylim([1e-6, 1]);
end

% --- 4. Save and Output ---
fig_filename = fullfile(results_dir, sprintf('BFC_Error_Rates_%s_E2_%.2f_replot.png', func_type, E2));
saveas(gcf, fig_filename);
fprintf('\n=== Plotting Complete ===\nPlot saved to: %s\n', fig_filename);
